sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    var records = api.data.look_up_multiple_records_1.results || [];
    if (records.length == 0) {
        api.emit("NOW_UXF_PAGE#ADD_NOTIFICATIONS", {

            items: [{
                id: "alert1",
                status: "critical",
                icon: "circle-exclamation-fill",
                content: {
                    type: "html",
                    value: "<h2>Nenhuma pergunta encontrada!</h2>"
                },
                action: {
                    type: "dismiss"
                }
            }]
        });
    }
}
